	"""Werte aus dem Formular (nur übergebene Felder) → Doc-Felder"""
	werte = {}
	for feld, doc_feld, lo, hi in (("mwp", "mwp", 0.01, 5000), ("anteilProzent", "anteil_prozent", 1, 100), ("kaufpreis", "kaufpreis", 0, 1e11), ("zusage", "zusage", 0, 1e11),
